-- MIGRACION DEFINITIVA CORREGIDA CABLE VIDEO IXCAN -> CUBITSERVICES
-- Incluye: clientes deduplicados, cuentas actuales clasificadas por tipo, 6 cuentas históricas de TV, cuentas contenedoras TV extra y política de cobro.
-- Generada contra schema(1).prisma y reglas validadas de migracion.
-- IMPORTANTE: reemplazar 11111111-1111-1111-1111-111111111111 antes de ejecutar.
-- Primera corrida termina en ROLLBACK; cambie a COMMIT solo despues de validar.

BEGIN;

-- ============================================================
-- CONTEOS ESPERADOS CON NUEVA ESTRATEGIA
-- Clientes deduplicados: 4809
-- Cuentas actuales principales: 975
-- Cuentas legacy inactivas: 4230
-- Cuentas históricas TV ya validadas: 6
-- Cuentas contenedoras TV Extra actuales: 73
-- TOTAL CuentaServicio esperado: 5284
--
-- Estados de las 4230 cuentas legacy inactivas:
--   SUSPENDIDA: 3386
--   CANCELADA: 137
--   FINALIZADA: 707
-- ============================================================


-- ============================================================
-- PREFLIGHT EMPRESA Y TIPOS DE SERVICIO BASE
-- La empresa, "Servicio de cable" y "TV Extra" se crean mediante el seed.
-- Este script NO crea esos dos tipos; únicamente valida que existan.
-- ============================================================
SELECT COUNT(*) AS empresa_existente
FROM empresa
WHERE id='11111111-1111-1111-1111-111111111111'::uuid;

SELECT nombre, id, precio_base, estado
FROM tipo_servicio
WHERE empresa_id='11111111-1111-1111-1111-111111111111'::uuid
  AND nombre IN ('Servicio de cable','TV Extra')
ORDER BY nombre;

DO $$
DECLARE
  v_empresa_id CONSTANT uuid := '11111111-1111-1111-1111-111111111111'::uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM empresa
    WHERE id=v_empresa_id
  ) THEN
    RAISE EXCEPTION
      'La empresa % no existe. Ejecuta el seed antes de esta migración.',
      v_empresa_id;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM tipo_servicio
    WHERE empresa_id=v_empresa_id
      AND nombre='Servicio de cable'
  ) THEN
    RAISE EXCEPTION
      'No existe el tipo de servicio "Servicio de cable" para la empresa %. Ejecuta el seed actualizado antes de esta migración.',
      v_empresa_id;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM tipo_servicio
    WHERE empresa_id=v_empresa_id
      AND nombre='TV Extra'
  ) THEN
    RAISE EXCEPTION
      'No existe el tipo de servicio "TV Extra" para la empresa %. Ejecuta el seed actualizado antes de esta migración.',
      v_empresa_id;
  END IF;
END $$;


-- "Servicio de cable" se obtiene del catálogo creado por el seed.
-- No se inserta aquí y su UUID se resuelve dinámicamente mediante empresa_id + nombre.


-- ============================================================
-- TIPOS DE SERVICIO ACTUALES VALIDADOS
-- Las velocidades representan TipoServicio, NO nuevas cuentas.
-- ============================================================
CREATE TEMP TABLE tmp_tipo_servicio_migracion (
  nombre varchar(120) PRIMARY KEY,
  descripcion text,
  precio_base numeric(12,2) NOT NULL
);


  id, empresa_id, nombre, descripcion, precio_base, estado,
  categoria_servicio, created_at, updated_at
)
SELECT
  gen_random_uuid(),
  '11111111-1111-1111-1111-111111111111'::uuid,
  t.nombre,
  t.descripcion,
  t.precio_base,
  'ACTIVO'::"EstadoRegistroBasico",
  'SERVICIO'::"CategoriaServicio",
  now(),
  now()
FROM tmp_tipo_servicio_migracion t
WHERE NOT EXISTS (
  SELECT 1
  FROM tipo_servicio ts
  WHERE ts.empresa_id='11111111-1111-1111-1111-111111111111'::uuid
    AND ts.nombre=t.nombre
);

-- ============================================================
-- TIPO DE SERVICIO PARA CUENTAS LEGACY INACTIVAS
-- No representa un plan comercial actual; evita inventar el tipo histórico.
-- ============================================================
  id, empresa_id, nombre, descripcion, precio_base, estado,
  categoria_servicio, created_at, updated_at
)
SELECT gen_random_uuid(),'11111111-1111-1111-1111-111111111111'::uuid,'Servicio histórico legacy',
       'Servicio legacy inactivo/finalizado conservado únicamente para historial',
       0.00,'ACTIVO'::"EstadoRegistroBasico",'SERVICIO'::"CategoriaServicio",now(),now()
WHERE NOT EXISTS (
  SELECT 1 FROM tipo_servicio
  WHERE empresa_id='11111111-1111-1111-1111-111111111111'::uuid AND nombre='Servicio histórico legacy'
);

-- ============================================================
-- CONFIGURACION COMERCIAL DE LA MIGRACION
-- ============================================================
-- El precio de TV Extra se toma directamente del TipoServicio creado
-- por el seed. Así el seed es la única fuente del precio base de TV Extra.
CREATE TEMP TABLE tmp_config_migracion AS
SELECT precio_base::numeric(12,2) AS precio_tv_extra
FROM tipo_servicio
WHERE empresa_id='11111111-1111-1111-1111-111111111111'::uuid
  AND nombre='TV Extra';

-- Debe resolverse exactamente una fila.
DO $$
DECLARE
  v_count integer;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM tmp_config_migracion;

  IF v_count <> 1 THEN
    RAISE EXCEPTION
      'No se pudo resolver de forma única TV Extra desde el seed. Registros encontrados: %',
      v_count;
  END IF;
END $$;

-- Una sola politica de cobro reutilizada por TODAS las cuentas migradas.
-- Configuracion neutral: mensual al fin de mes, sin mora automatica.
-- Si luego el negocio cambia la politica, se edita el catalogo; no hay que
-- modificar cuenta por cuenta.
  id, empresa_id, nombre, tipo_vencimiento, dia_corte, dia_vencimiento,
  dias_gracia, tipo_mora, valor_mora, aplica_mora, estado,
  created_at, updated_at
)
SELECT
  gen_random_uuid(),
  '11111111-1111-1111-1111-111111111111'::uuid,
  'Política mensual Cable Video Ixcan',
  'FIN_MES'::"TipoVencimiento",
  NULL,
  NULL,
  0,
  NULL,
  NULL,
  false,
  'ACTIVO'::"EstadoRegistroBasico",
  now(), now()
WHERE NOT EXISTS (
  SELECT 1
  FROM politica_cobro
  WHERE empresa_id='11111111-1111-1111-1111-111111111111'::uuid
    AND nombre='Política mensual Cable Video Ixcan'
);

