-- Esperado: ACTIVO=978, INACTIVO=4224

-- ============================================================
-- DEDUPLICACION DEFINITIVA DE CLIENTES - FASE 1
-- Solo opera sobre tmp_cliente_migracion, que ya existe en este punto.
-- ============================================================
CREATE TEMP TABLE tmp_cliente_dedup (
  legacy_codigo varchar(50) PRIMARY KEY,
  canonical_codigo varchar(50) NOT NULL
);


-- ============================================================
-- DEDUPLICACION ADICIONAL V11
-- 45 grupos validados con direcciones distintas.
-- Canónico: registro ACTIVO cuando existe; si todos son INACTIVOS,
-- se conserva el menor código legacy.
-- Los 2 grupos con direcciones idénticas quedan fuera para revisión manual.
-- ============================================================

-- Fusionar estado y observaciones en el cliente canónico.
WITH miembros AS (
  SELECT d.canonical_codigo, c.estado, c.observaciones
  FROM tmp_cliente_dedup d
  JOIN tmp_cliente_migracion c ON c.codigo=d.legacy_codigo
  UNION ALL
  SELECT c.codigo, c.estado, c.observaciones
  FROM tmp_cliente_migracion c
  WHERE c.codigo IN (SELECT DISTINCT canonical_codigo FROM tmp_cliente_dedup)
), agg AS (
  SELECT canonical_codigo,
         CASE WHEN bool_or(estado='ACTIVO') THEN 'ACTIVO' ELSE 'INACTIVO' END AS estado_final,
         string_agg(DISTINCT NULLIF(btrim(observaciones),''),
                    E'\n\n--- Registro legacy consolidado ---\n\n')
           FILTER (WHERE observaciones IS NOT NULL AND btrim(observaciones) <> '') AS observaciones_final
  FROM miembros
  GROUP BY canonical_codigo
)
UPDATE tmp_cliente_migracion c
SET estado=a.estado_final,
    observaciones=COALESCE(a.observaciones_final,c.observaciones)
FROM agg a
WHERE c.codigo=a.canonical_codigo;

-- Completar datos faltantes del canónico con datos de duplicados.
WITH datos AS (
  SELECT d.canonical_codigo,
         max(NULLIF(c.telefono,'')) FILTER (WHERE c.telefono IS NOT NULL AND c.telefono <> '') AS telefono,
         max(NULLIF(c.identificacion,'')) FILTER (WHERE c.identificacion IS NOT NULL AND c.identificacion <> '') AS identificacion,
         max(NULLIF(c.tipo_identificacion,'')) FILTER (WHERE c.tipo_identificacion IS NOT NULL AND c.tipo_identificacion <> '') AS tipo_identificacion
  FROM tmp_cliente_dedup d
  JOIN tmp_cliente_migracion c ON c.codigo=d.legacy_codigo
  GROUP BY d.canonical_codigo
)
UPDATE tmp_cliente_migracion c
SET telefono=COALESCE(c.telefono,d.telefono),
    identificacion=COALESCE(c.identificacion,d.identificacion),
    tipo_identificacion=COALESCE(c.tipo_identificacion,d.tipo_identificacion)
FROM datos d
WHERE c.codigo=d.canonical_codigo;

-- Eliminar únicamente las filas Cliente duplicadas.
DELETE FROM tmp_cliente_migracion c
USING tmp_cliente_dedup d
WHERE c.codigo=d.legacy_codigo;

-- V11: debe devolver 4760 (4809 previos - 49 clientes adicionales fusionados).
SELECT COUNT(*) AS clientes_deduplicados_preparados FROM tmp_cliente_migracion;

SELECT id, '11111111-1111-1111-1111-111111111111'::uuid, codigo, tipo_cliente::"TipoCliente", NULL,NULL,NULL,NULL,nombre_razon_social,NULL, CASE WHEN tipo_identificacion IS NULL THEN NULL ELSE tipo_identificacion::"TipoIdentificacion" END, NULLIF(identificacion,''), NULLIF(telefono,''), NULL,NULL, estado::"EstadoRegistroBasico", NULLIF(observaciones,''), now(),now() FROM tmp_cliente_migracion;

CREATE TEMP TABLE tmp_ubicacion_migracion (id uuid PRIMARY KEY, legacy_key varchar(50), cliente_codigo varchar(50), nombre varchar(120), direccion text, referencia text, es_principal boolean, estado text, zona int, calle int, avenida int, numero_casa int);

-- DEDUPLICACION - FASE 2: reasignar ubicaciones al cliente canónico.
UPDATE tmp_ubicacion_migracion u
SET cliente_codigo=d.canonical_codigo
FROM tmp_cliente_dedup d
WHERE u.cliente_codigo=d.legacy_codigo;

SELECT u.id,c.id,u.nombre,u.direccion,NULLIF(u.referencia,''),NULL,NULL,u.es_principal,u.estado::"EstadoUbicacion",u.zona,u.calle,u.avenida,u.numero_casa,now(),now() FROM tmp_ubicacion_migracion u JOIN tmp_cliente_migracion c ON c.codigo=u.cliente_codigo;

CREATE TEMP TABLE tmp_cuenta_migracion (id uuid PRIMARY KEY, codigo varchar(50), cliente_codigo varchar(50), legacy_location_key varchar(50), nombre varchar(180), modalidad text, frecuencia text, fecha_inicio date, monto_base numeric(12,2), estado text, observaciones jsonb);


-- ============================================================
-- CUENTA CONTENEDORA DE TV EXTRAS
-- Se crea UNA sola CuentaServicio adicional por servicio legacy activo con Extra > 0.
-- tv_extra = BANCO DATOS.Extra
-- monto_base = precio unitario TV Extra (Q15) * tv_extra
-- Código: <legacy_id>-TVE
-- Comparte cliente, ubicación y política de cobro con el servicio principal.
-- ============================================================
CREATE TEMP TABLE tmp_cuenta_tv_extra_migracion (
  id uuid PRIMARY KEY,
  codigo varchar(50) NOT NULL,
  cliente_codigo varchar(50) NOT NULL,
  legacy_location_key varchar(50) NOT NULL,
  tv_extra integer NOT NULL CHECK (tv_extra > 0),
  estado text NOT NULL,
  observaciones jsonb
);

-- DEDUPLICACION - FASE 4: reasignar cuentas TV Extra al cliente canónico.
UPDATE tmp_cuenta_tv_extra_migracion e
SET cliente_codigo=d.canonical_codigo
FROM tmp_cliente_dedup d
WHERE e.cliente_codigo=d.legacy_codigo;

-- Preflight de códigos de cuentas contenedoras TV Extra: debe devolver 0.
SELECT COUNT(*) AS conflictos_codigo_tv_extra
FROM tmp_cuenta_tv_extra_migracion t
JOIN cuenta_servicio c
  ON c.empresa_id='11111111-1111-1111-1111-111111111111'::uuid
 AND c.codigo=t.codigo;


-- Preflight: debe devolver 0.

