-- Validación de estados de cliente
SELECT estado, COUNT(*) AS cantidad
FROM tmp_cliente_migracion
GROUP BY estado
ORDER BY estado;


-- ============================================================
-- VALIDACIONES CRITICAS V11
-- ============================================================

-- A. 9370 debe existir como cuenta principal ACTIVA.
SELECT
  cs.codigo,
  cs.estado,
  c.codigo AS cliente_codigo,
  c.nombre_razon_social,
  ts.nombre AS tipo_servicio
FROM cuenta_servicio cs
JOIN cliente c ON c.id=cs.cliente_id
JOIN tipo_servicio ts ON ts.id=cs.tipo_servicio_id
WHERE cs.empresa_id='11111111-1111-1111-1111-111111111111'::uuid
  AND cs.codigo IN ('9370','9370-HIST-TV')
ORDER BY cs.codigo;

-- B. Debe existir exactamente una cuenta principal 9370.
SELECT COUNT(*) AS cantidad_cuenta_principal_9370
FROM cuenta_servicio
WHERE empresa_id='11111111-1111-1111-1111-111111111111'::uuid
  AND codigo='9370'
  AND estado='ACTIVA'::"EstadoCuentaServicio";

-- C. Ningún código legacy fusionado debe seguir existiendo como Cliente independiente.
SELECT COUNT(*) AS clientes_legacy_deduplicados_que_aun_existen
FROM cliente c
JOIN tmp_cliente_dedup d ON d.legacy_codigo=c.codigo
WHERE c.empresa_id='11111111-1111-1111-1111-111111111111'::uuid;

-- D. Todas las cuentas principales de códigos fusionados deben seguir existiendo
-- y apuntar al cliente canónico.
SELECT COUNT(*) AS cuentas_deduplicadas_con_cliente_incorrecto
FROM cuenta_servicio cs
JOIN tmp_cliente_dedup d ON d.legacy_codigo=cs.codigo
JOIN cliente c ON c.id=cs.cliente_id
WHERE cs.empresa_id='11111111-1111-1111-1111-111111111111'::uuid
  AND c.codigo<>d.canonical_codigo;

-- E. Conteo físico final de CuentaServicio: esperado 5285 mientras
-- se conserven las seis cuentas HIST-TV.
SELECT COUNT(*) AS total_cuentas_servicio_v11
FROM cuenta_servicio
WHERE empresa_id='11111111-1111-1111-1111-111111111111'::uuid;

-- F. Desglose final para explicar el total.
SELECT
  COUNT(*) FILTER (WHERE codigo LIKE '%-TVE') AS tv_extra,
  COUNT(*) FILTER (WHERE codigo LIKE '%-HIST-TV') AS historicas_tv,
  COUNT(*) FILTER (
    WHERE codigo NOT LIKE '%-TVE'
      AND codigo NOT LIKE '%-HIST-TV'
  ) AS cuentas_principales,
  COUNT(*) AS total
FROM cuenta_servicio
WHERE empresa_id='11111111-1111-1111-1111-111111111111'::uuid;

-- G. Los dos grupos pendientes deben seguir visibles para revisión manual.
SELECT codigo,nombre_razon_social,telefono,identificacion,estado
FROM cliente
WHERE empresa_id='11111111-1111-1111-1111-111111111111'::uuid
  AND codigo IN ('10013','10159','10311','1146')
ORDER BY nombre_razon_social,codigo;


-- H. Validación de períodos adelantados preservados.
-- Debe devolver 26 cuentas.
SELECT
  cs.codigo,
  c.nombre_razon_social,
  cs.estado,
  elem->>'texto' AS informacion_periodo_adelantado
FROM cuenta_servicio cs
JOIN cliente c ON c.id=cs.cliente_id
CROSS JOIN LATERAL jsonb_array_elements(COALESCE(cs.observaciones,'[]'::jsonb)) elem
WHERE cs.empresa_id='11111111-1111-1111-1111-111111111111'::uuid
  AND elem->>'texto' LIKE 'Información legacy de cobro: período registrado por adelantado hasta %'
ORDER BY cs.codigo;

